-- PURPOSE: Check beginner lesson progression and concrete public-count exercises.
-- CHANGE THIS MODULE WHEN: Learn Hi-Lo lessons or locked conventions change.
-- DO NOT PUT HERE: Expected answers generated by tutorial or count helpers.

local test = require("tests.harness")
local tutorial = require("src.training.tutorial")
local copy = require("src.plain_copy")
local tutorial_tests = {}
local exercise_answers = {
    [2] = 1,
    [3] = -1,
    [5] = 1,
    [6] = 0,
    [8] = 6,
    [9] = 1,
    [11] = 2,
    [12] = -2,
    [14] = 2,
    [15] = 1,
}

local function at_page(page_number)
    local state = tutorial.new()
    while state.index < page_number do
        local expected = exercise_answers[state.index]
        if expected ~= nil then
            assert(tutorial.answer(state, expected))
        end
        assert(tutorial.advance(state))
    end
    return state
end

function tutorial_tests.run()
    test.test("Learn Hi-Lo starts with tags before running or true counts", function()
        local state = tutorial.new()
        local page = tutorial.current(state)
        test.equal(page.stage, 1)
        test.equal(page.page_number, 1)
        test.equal(page.page_count, 15)
        test.equal(page.exercise, nil)
        test.equal(state.complete, false)
    end)
    test.test("the five lesson stages stay ordered with ten short exercises", function()
        local state = tutorial.new()
        local previous_stage, exercise_count = 0, 0
        for page_number = 1, 15 do
            local page = tutorial.current(state)
            assert(page.stage >= previous_stage)
            assert(page.stage <= previous_stage + 1)
            previous_stage = page.stage
            if page.exercise then
                exercise_count = exercise_count + 1
                local feedback = assert(tutorial.answer(state, exercise_answers[page_number]))
                test.equal(feedback.correct, true, "Page " .. page_number)
                assert(#feedback.explanation > 0)
            end
            assert(tutorial.advance(state))
        end
        test.equal(exercise_count, 10)
        test.equal(previous_stage, 5)
        test.equal(state.complete, true)
        test.equal(tutorial.current(state).complete, true)
        assert(not tutorial.advance(state))
    end)
    test.test("low six tags plus one and King tags minus one", function()
        test.equal(assert(tutorial.answer(at_page(2), 1)).correct, true)
        test.equal(assert(tutorial.answer(at_page(3), -1)).correct, true)
    end)
    test.test("running counts teach accumulating and cancelling tags", function()
        test.equal(assert(tutorial.answer(at_page(5), 1)).correct, true, "2 + 6 + Queen")
        test.equal(assert(tutorial.answer(at_page(6), 0)).correct, true, "Ace + 3 + 5 + King")
    end)
    test.test("deck exercise rounds 2.8 upward to six half-deck steps", function()
        local feedback = assert(tutorial.answer(at_page(8), 6))
        test.equal(feedback.correct, true)
        test.equal(feedback.expected, 6)
        assert(feedback.explanation:find("3 estimated decks", 1, true))
    end)
    test.test("twelve unexposed cards still use one half-deck step", function()
        test.equal(assert(tutorial.answer(at_page(9), 1)).correct, true)
    end)
    test.test("positive 2.8 becomes plus two and negative 2.8 becomes minus two", function()
        test.equal(assert(tutorial.answer(at_page(11), 2)).correct, true)
        test.equal(assert(tutorial.answer(at_page(12), -2)).correct, true)
        local wrong = assert(tutorial.answer(at_page(12), -3))
        test.equal(wrong.correct, false)
        test.equal(wrong.expected, -2)
    end)
    test.test("practice leaves the hidden hole out until its Ace is revealed", function()
        local hidden = at_page(14)
        test.equal(tutorial.current(hidden).hidden_card, true)
        test.equal(#tutorial.current(hidden).card_ids, 3)
        test.equal(assert(tutorial.answer(hidden, 2)).correct, true)
        assert(tutorial.advance(hidden))
        test.equal(tutorial.current(hidden).hidden_card, nil)
        test.equal(#tutorial.current(hidden).card_ids, 4)
        test.equal(assert(tutorial.answer(hidden, 1)).correct, true)
    end)
    test.test("an unanswered exercise cannot silently advance", function()
        local state = at_page(2)
        local before = copy(state)
        assert(not tutorial.advance(state))
        test.same(state, before)
    end)
    test.test("incorrect answers explain the expected value before Next", function()
        local state = at_page(5)
        local feedback = assert(tutorial.answer(state, -1))
        test.equal(feedback.correct, false)
        test.equal(feedback.expected, 1)
        assert(feedback.explanation:find("Queen (-1)", 1, true) == nil)
        assert(feedback.explanation:find("Q (-1)", 1, true))
        assert(tutorial.advance(state))
        test.equal(state.feedback, nil)
    end)
    test.test(
        "reading a lesson or mutating returned feedback cannot change tutorial state",
        function()
            local state = at_page(2)
            local first_page = tutorial.current(state)
            first_page.lines[1] = "Changed externally"
            test.equal(tutorial.current(state).lines[1], "A low card leaving the shoe adds one.")
            local feedback = assert(tutorial.answer(state, 0))
            feedback.correct = true
            test.equal(tutorial.current(state).feedback.correct, false)
            test.equal(
                assert(tutorial.answer(state, 1)).correct,
                false,
                "The same exercise is already answered"
            )
        end
    )
    test.test("lessons and invalid fractional answers do not record an exercise", function()
        assert(not tutorial.answer(tutorial.new(), 1))
        for _, answer in ipairs({ 0.5, 417, -417, math.huge, "1" }) do
            local state = at_page(2)
            assert(not tutorial.answer(state, answer))
            test.equal(state.feedback, nil)
        end
    end)
    test.test("identical tutorial input produces identical deterministic feedback", function()
        local first, second = at_page(12), at_page(12)
        test.same(assert(tutorial.answer(first, -2)), assert(tutorial.answer(second, -2)))
        test.same(first, second)
    end)
end

return tutorial_tests
